function validate(input) {
  const [obj, fn] = input;
  const isContainer = value => value !== null && typeof value === 'object';
  if (!isContainer(obj)) return 'obj must be a JSON object or array.';
  const size = JSON.stringify(obj).length;
  if (size < 2 || size > 100000) return 'obj must be 2 to 100,000 characters of JSON.';
  const stack = [obj];
  while (stack.length) {
    const item = stack.pop();
    if (!isContainer(item)) continue;
    if (!Array.isArray(item) && Object.hasOwn(item, '__proto__')) return 'Keys named "__proto__" are not allowed.';
    for (const key of Object.keys(item)) stack.push(item[key]);
  }
  // Follows a path through obj; returns undefined when it leaves obj.
  const has = (container, key) => Array.isArray(container) ? Number.isInteger(key) && key >= 0 && key < container.length : typeof key === 'string' && Object.hasOwn(container, key);
  const reach = path => {
    let value = obj;
    for (const key of path) {
      if (!isContainer(value) || !has(value, key)) return undefined;
      value = value[key];
    }
    return value;
  };
  const isPath = path => Array.isArray(path) && path.length <= 12 && path.every(key => typeof key === 'string' || Number.isInteger(key));
  const methods = ['pop', 'push', 'shift', 'unshift', 'splice', 'sort', 'reverse', 'slice', 'indexOf', 'lastIndexOf', 'includes', 'join', 'at', 'concat'];
  if (!Array.isArray(fn) || fn.length < 1 || fn.length > 10) return 'fn must be a list of 1 to 10 steps.';
  for (const step of fn) {
    const kinds = isContainer(step) && !Array.isArray(step) ? Object.keys(step) : [];
    const kind = ['set', 'call', 'get', 'keys', 'return'].find(name => kinds.includes(name));
    if (!kind) return 'Each step is {"set", "value"}, {"call", "args"}, {"get"}, {"keys"} or {"return"}.';
    if (kind === 'return') {
      if (kinds.length !== 1) return 'A return step has only the key "return".';
      continue;
    }
    const path = step[kind];
    if (!isPath(path)) return 'A path is a list of string keys and integer indexes.';
    if (kind === 'set') {
      if (kinds.length !== 2 || !kinds.includes('value') || path.length === 0) return 'A set step is {"set": path, "value": v} with a non-empty path.';
      const parent = reach(path.slice(0, -1)), key = path[path.length - 1];
      if (!isContainer(parent)) return `set ${JSON.stringify(path)} must assign inside an object or array of obj.`;
      if (Array.isArray(parent) ? !Number.isInteger(key) || key < 0 || key > 2000 : typeof key !== 'string') return 'set assigns to a string key of an object or an index 0 to 2000 of an array.';
    } else if (kind === 'call') {
      if (kinds.length !== 2 || !Array.isArray(step.args) || step.args.length > 5 || path.length === 0) return 'A call step is {"call": path, "args": list of at most 5 values}.';
      if (!Array.isArray(reach(path.slice(0, -1))) || !methods.includes(path[path.length - 1])) return `call ${JSON.stringify(path)} must name a listed method of an array of obj.`;
    } else if (kind === 'get') {
      if (kinds.length !== 1) return 'A get step has only the key "get".';
      const parent = reach(path.slice(0, -1)), key = path[path.length - 1];
      const isLength = Array.isArray(parent) && key === 'length';
      if (path.length > 0 && !isLength && (!isContainer(parent) || !has(parent, key))) return `get ${JSON.stringify(path)} must name a value in obj.`;
    } else {
      if (kinds.length !== 1 || !isContainer(reach(path))) return 'A keys step names an object or array of obj.';
    }
  }
  return null;
}

