function adapt(input, solve, kit) {
  const [obj, fn] = input;
  const immutable = solve(obj);
  if (immutable === null || typeof immutable !== 'object') throw new Error('makeImmutable must return an object or an array.');
  kit.trace('makeImmutable(obj) returns the immutable value im');
  const show = path => 'im' + path.map(key => typeof key === 'number' ? `[${key}]` : /^[A-Za-z_$][\w$]*$/.test(key) ? `.${key}` : `[${JSON.stringify(key)}]`).join('');
  const reach = path => path.reduce((value, key) => value[key], immutable);
  let result;
  try {
    for (const step of fn) {
      if ('set' in step) {
        const parent = reach(step.set.slice(0, -1));
        kit.trace(`${show(step.set)} = ${JSON.stringify(step.value)} is attempted`);
        parent[step.set[step.set.length - 1]] = step.value;
        result = step.value;
      } else if ('call' in step) {
        const target = reach(step.call.slice(0, -1)), method = step.call[step.call.length - 1];
        kit.trace(`${show(step.call)}(${step.args.map(arg => JSON.stringify(arg)).join(', ')}) is called`);
        result = target[method](...step.args);
      } else if ('get' in step) {
        result = reach(step.get);
        kit.trace(`${show(step.get)} reads ${JSON.stringify(result)}`);
      } else if ('keys' in step) {
        result = Object.keys(reach(step.keys));
        kit.trace(`Object.keys(${show(step.keys)}) gives ${JSON.stringify(result)}`);
      } else {
        result = step.return;
      }
    }
  } catch (error) {
    const text = typeof error === 'string' ? error : `${error instanceof Error ? error.name : typeof error} thrown instead of a string: ${error instanceof Error ? error.message : String(error)}`;
    kit.trace(`it throws ${JSON.stringify(text)}`);
    return { value: null, error: text };
  }
  const value = result === undefined ? null : result;
  kit.trace(`fn returns ${JSON.stringify(value)} without an error`);
  return { value, error: null };
}

