function makeImmutable(obj) {
  const mutators = new Set(['pop', 'push', 'shift', 'unshift', 'splice', 'sort', 'reverse']);
  const handler = {
    set(target, key) {
      if (Array.isArray(target)) {
        throw `Error Modifying Index: ${key}`;
      }
      throw `Error Modifying: ${key}`;
    },
    get(target, key) {
      if (Array.isArray(target) && mutators.has(key)) {
        return () => {
          throw `Error Calling Method: ${key}`;
        };
      }
      return target[key];
    },
  };
  const wrap = (value) => {
    if (value === null || typeof value !== 'object') {
      return value;
    }
    const copy = Array.isArray(value) ? [] : {};
    for (const key of Object.keys(value)) {
      copy[key] = wrap(value[key]);
    }
    return new Proxy(copy, handler);
  };
  return wrap(obj);
}

