function makeImmutable(obj) {
  // Wrap lazily: obj itself sits behind the proxy, and a nested object or array is wrapped each time it is read.
  return new Proxy(obj, {
    set(target, key) {
      throw (Array.isArray(target) ? 'Error Modifying Index: ' : 'Error Modifying: ') + String(key);
    },
    get(target, key) {
      if (Array.isArray(target) && ['pop', 'push', 'shift', 'unshift', 'splice', 'sort', 'reverse'].indexOf(key) >= 0) {
        return function () { throw 'Error Calling Method: ' + key; };
      }
      const value = target[key];
      return value !== null && typeof value === 'object' ? makeImmutable(value) : value;
    },
  });
}

