function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['a', 'b', 'x', 'y', 'arr', 'name', 'list', 'k'];
  let budget = small ? 10 : 3000;
  const primitive = () => {
    const roll = rand();
    if (roll < 0.5) return Math.floor(rand() * 21) - 5;
    if (roll < 0.75) return pick(['', 'a', 'hi', 'x']);
    if (roll < 0.9) return rand() < 0.5;
    return null;
  };
  const value = (depth, container) => {
    budget--;
    if (!container && (depth >= (small ? 3 : 6) || budget <= 0 || rand() < 0.45)) return primitive();
    const length = depth === 0 && !small ? 40 : Math.floor(rand() * (small ? 4 : 7));
    if (rand() < 0.5) return Array.from({ length }, () => value(depth + 1, false));
    const object = {};
    for (let i = 0; i < length; i++) object[pick(names) + (small ? '' : i)] = value(depth + 1, false);
    return object;
  };
  const obj = value(0, true);
  // Every object and array of obj, with the path that reaches it.
  const containers = [];
  const walk = (item, path) => {
    if (item === null || typeof item !== 'object') return;
    containers.push([item, path]);
    for (const key of Object.keys(item)) walk(item[key], [...path, Array.isArray(item) ? Number(key) : key]);
  };
  walk(obj, []);
  const reads = ['slice', 'indexOf', 'lastIndexOf', 'includes', 'join', 'at', 'concat'];
  const writes = ['pop', 'push', 'shift', 'unshift', 'splice', 'sort', 'reverse'];
  const steps = [], count = 1 + Math.floor(rand() * 4);
  for (let i = 0; i < count; i++) {
    const [item, path] = pick(containers);
    const isArray = Array.isArray(item), keys = Object.keys(item).map(key => (isArray ? Number(key) : key));
    const roll = rand();
    if (roll < 0.25 && keys.length) steps.push({ get: [...path, pick(keys)] });
    else if (roll < 0.35) steps.push({ get: isArray ? [...path, 'length'] : path });
    else if (roll < 0.45) steps.push({ keys: path });
    else if (roll < 0.55 && isArray) steps.push({ call: [...path, pick(reads)], args: rand() < 0.5 ? [] : [Math.floor(rand() * 5) - 1] });
    else if (roll < 0.6) steps.push({ return: primitive() });
    else if (roll < 0.85 || !isArray) {
      const key = isArray ? Math.floor(rand() * (keys.length + 2)) : keys.length && rand() < 0.6 ? pick(keys) : pick(names) + 'New';
      steps.push({ set: [...path, key], value: rand() < 0.2 ? {} : primitive() });
    } else steps.push({ call: [...path, pick(writes)], args: Array.from({ length: Math.floor(rand() * 3) }, primitive) });
  }
  return [obj, steps];
}
